"use client"

import { Bookmark, Edit2, Plus } from "lucide-react"
import { useEffect, useId, useState } from "react"
import { Button } from "@/components/ui/button"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import { useDictionary } from "@/hooks/use-dictionary"
import {
    createTemplate,
    type Template,
    updateTemplate,
} from "@/lib/template-storage"

interface TemplateFormDialogProps {
    open: boolean
    onOpenChange: (open: boolean) => void
    onSuccess: () => void
    /** The template to edit; without one the dialog creates a new template */
    template?: Template | null
    initialPrompt?: string
}

// One form for creating and editing a template
export function TemplateFormDialog({
    open,
    onOpenChange,
    onSuccess,
    template,
    initialPrompt = "",
}: TemplateFormDialogProps) {
    const dict = useDictionary()
    const id = useId()
    const isEdit = !!template
    const [title, setTitle] = useState("")
    const [description, setDescription] = useState("")
    const [prompt, setPrompt] = useState("")
    const [pinned, setPinned] = useState(false)
    const [isSubmitting, setIsSubmitting] = useState(false)
    const [error, setError] = useState<string | null>(null)

    // Fill the form each time the dialog opens, dropping cancelled edits
    useEffect(() => {
        if (!open) return
        setTitle(template?.title || "")
        setDescription(template?.description || "")
        setPrompt(template ? template.prompt || "" : initialPrompt)
        setPinned(template?.pinned || false)
        setError(null)
    }, [open, template, initialPrompt])

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault()
        // React submit events bubble through the portal; keep them away from
        // the chat form this dialog may be rendered in
        e.stopPropagation()

        const trimmedPrompt = prompt.trim()
        if (!trimmedPrompt) {
            setError(dict.templates.promptRequired)
            return
        }

        setIsSubmitting(true)
        setError(null)

        const failed = isEdit
            ? dict.templates.updateFailed
            : dict.templates.createFailed
        try {
            const fields = {
                prompt: trimmedPrompt,
                description: description.trim() || undefined,
                pinned,
            }
            // An emptied title keeps the old one when editing; a new template
            // gets a default title from its prompt
            const result = template
                ? await updateTemplate(template.id, {
                      ...fields,
                      title: title.trim() || template.title,
                  })
                : await createTemplate({
                      ...fields,
                      title: title.trim() || undefined,
                  })
            if (result) {
                onSuccess()
                onOpenChange(false)
            } else {
                setError(failed)
            }
        } finally {
            setIsSubmitting(false)
        }
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[500px] overflow-hidden">
                <form onSubmit={handleSubmit}>
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            {isEdit ? (
                                <Edit2 className="w-5 h-5" />
                            ) : (
                                <Plus className="w-5 h-5" />
                            )}
                            {isEdit
                                ? dict.templates.editTitle
                                : dict.templates.createTitle}
                        </DialogTitle>
                        <DialogDescription>
                            {isEdit
                                ? dict.templates.editDescription
                                : dict.templates.createDescription}
                        </DialogDescription>
                    </DialogHeader>

                    <div className="space-y-4 py-4">
                        {/* Prompt field - required */}
                        <div className="space-y-2">
                            <Label
                                htmlFor={`${id}-prompt`}
                                className="text-foreground"
                            >
                                {dict.templates.promptLabel}
                                <span className="text-destructive ml-1">*</span>
                            </Label>
                            <Textarea
                                id={`${id}-prompt`}
                                value={prompt}
                                onChange={(e) => setPrompt(e.target.value)}
                                placeholder={dict.templates.promptPlaceholder}
                                className="min-h-[100px] resize-none break-words"
                                required
                            />
                        </div>

                        {/* Title field - optional */}
                        <div className="space-y-2">
                            <Label
                                htmlFor={`${id}-title`}
                                className="text-foreground"
                            >
                                {dict.templates.titleLabel}
                            </Label>
                            <Input
                                id={`${id}-title`}
                                value={title}
                                onChange={(e) => setTitle(e.target.value)}
                                placeholder={dict.templates.titlePlaceholder}
                            />
                            <p className="text-xs text-muted-foreground">
                                {dict.templates.titleHint}
                            </p>
                        </div>

                        {/* Description field - optional */}
                        <div className="space-y-2">
                            <Label
                                htmlFor={`${id}-description`}
                                className="text-foreground"
                            >
                                {dict.templates.descriptionLabel}
                            </Label>
                            <Textarea
                                id={`${id}-description`}
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                placeholder={
                                    dict.templates.descriptionPlaceholder
                                }
                                className="min-h-[60px] resize-none"
                            />
                        </div>

                        {/* Pinned switch */}
                        <div className="flex items-center justify-between">
                            <div className="space-y-0.5">
                                <Label
                                    htmlFor={`${id}-pinned`}
                                    className="flex items-center gap-2 text-foreground"
                                >
                                    <Bookmark className="w-4 h-4" />
                                    {dict.templates.pinnedLabel}
                                </Label>
                                <p className="text-xs text-muted-foreground">
                                    {dict.templates.pinnedHint}
                                </p>
                            </div>
                            <Switch
                                id={`${id}-pinned`}
                                checked={pinned}
                                onCheckedChange={setPinned}
                            />
                        </div>

                        {/* Error message */}
                        {error && (
                            <p className="text-sm text-destructive">{error}</p>
                        )}
                    </div>

                    <DialogFooter>
                        <Button
                            type="button"
                            variant="outline"
                            onClick={() => onOpenChange(false)}
                            disabled={isSubmitting}
                        >
                            {dict.common.cancel}
                        </Button>
                        <Button type="submit" disabled={isSubmitting}>
                            {isSubmitting
                                ? dict.common.loading
                                : isEdit
                                  ? dict.common.save
                                  : dict.templates.createButton}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    )
}
import { Pencil, Redo2, RotateCcw, Undo2 } from "lucide-react"
import { useMemo } from "react"
import { Shimmer } from "@/components/ai-elements/shimmer"
import {
    useVersionsContext,
    type VersionItem,
} from "@/components/canvas/versions-context"
import { useDictionary } from "@/hooks/use-dictionary"
import { pageNameOf } from "@/lib/diagram-pages"
import { highlightChangedCells } from "@/lib/drawio/editor-bridge"
import { formatMessage } from "@/lib/i18n/utils"
import { cn } from "@/lib/utils"
import { describeChangeSummary, describeTotals } from "@/lib/version-text"
import { useUiStore } from "@/stores/ui-store"

/** Picture of a version (SVG data URL), or what stands in for it */
export function VersionThumb({
    svg,
    dimmed,
    className,
}: {
    /** undefined or null: still being made; "": none could be made */
    svg: string | null | undefined
    dimmed?: boolean
    className?: string
}) {
    const t = useDictionary().versions
    if (svg) {
        return (
            // biome-ignore lint/performance/noImgElement: data URL thumbnail
            <img
                src={svg}
                alt=""
                className={cn(
                    "object-contain transition-opacity",
                    dimmed && "opacity-40",
                    className,
                )}
            />
        )
    }
    if (svg === "") {
        return <span className="text-xs text-faint">{t.noPreview}</span>
    }
    return (
        <Shimmer as="span" className="text-xs">
            {t.rendering}
        </Shimmer>
    )
}

interface VersionCardProps extends React.ComponentProps<"div"> {
    version: VersionItem
    /** The newest version shows its picture; older ones fold into one row */
    isLatest: boolean
    /** What happened ("Drew the diagram"); an undone change says so instead */
    label: string
    /** Goes after the summary text (the chat adds its "Show XML" link) */
    afterSummary?: React.ReactNode
    /** The canvas was changed by hand since this version: the card says so */
    editedSince?: boolean
    /** Panel below the card (the chat shows the AI's XML there) */
    children?: React.ReactNode
}

/** A link in the card's summary line, after a separator */
export function SummaryLink({
    onClick,
    children,
}: {
    onClick: () => void
    children: React.ReactNode
}) {
    // A text link, so the card's only button is the action (undo or
    // restore); it wraps as one unit with its separator
    return (
        <span className="whitespace-nowrap">
            <span aria-hidden> · </span>
            <button
                type="button"
                onClick={onClick}
                className="underline decoration-foreground/30 underline-offset-2 hover:text-foreground hover:decoration-foreground"
            >
                {children}
            </button>
        </span>
    )
}

/**
 * Card for one diagram version: picture, number, label, what changed, and
 * the action (undo or redo on the latest, restore on older ones). The
 * picture opens Compare. Other attributes go on the card's element.
 */
export function VersionCard({
    version,
    isLatest,
    label,
    afterSummary,
    editedSince,
    children,
    className,
    ...rest
}: VersionCardProps) {
    const t = useDictionary().versions
    const source = useVersionsContext()
    const openCompare = useUiStore((s) => s.openCompare)

    const isUndone = source.undoneId === version.id
    const isOnCanvas = source.onCanvasId === version.id
    const title = isUndone ? t.undone : label
    const summary = version.fromScratch
        ? describeTotals(version.summary, t)
        : describeChangeSummary(version.summary, t)
    // In a document with several pages, the page the change was made on
    const pageName = useMemo(
        () => pageNameOf(version.xml, version.pageId),
        [version.xml, version.pageId],
    )
    // The outline of the change, again, for the version on the canvas (a
    // diagram drawn from nothing is outlined nowhere)
    const canShowChanges =
        isOnCanvas && !version.fromScratch && !!version.touchedIds?.length
    const badge = (
        <span
            className={cn(
                "shrink-0 rounded-md px-1.5 py-0.5 text-[11px] font-semibold tabular-nums",
                isOnCanvas
                    ? "bg-marker-soft text-marker-ink"
                    : "bg-muted text-muted-foreground",
            )}
        >
            v{version.number}
        </span>
    )
    const actionClass =
        "inline-flex h-7 shrink-0 items-center gap-1 rounded-lg px-2 text-xs text-muted-foreground hover:bg-accent hover:text-foreground disabled:opacity-40"
    const restoreButton = (
        <button
            type="button"
            disabled={source.isBusy || isOnCanvas}
            onClick={() => source.restore(version.id)}
            className={actionClass}
            data-testid="version-restore"
        >
            <RotateCcw className="size-3.5" />
            {formatMessage(t.restoreVersion, { n: version.number })}
        </button>
    )
    const summaryLine = (
        <div className="text-xs text-muted-foreground">
            {pageName && (
                <span className="font-medium text-foreground/80">
                    {pageName}:{" "}
                </span>
            )}
            {summary}
            {canShowChanges && (
                <SummaryLink
                    onClick={() =>
                        highlightChangedCells(
                            version.touchedIds ?? [],
                            version.pageId,
                        )
                    }
                >
                    {t.showChanges}
                </SummaryLink>
            )}
            {afterSummary}
            {editedSince && (
                <div
                    className="mt-1 flex items-center gap-1 text-foreground/80"
                    data-testid="version-edited-since"
                >
                    <Pencil className="size-3 shrink-0" />
                    {t.editedSince}
                </div>
            )}
        </div>
    )

    if (!isLatest) {
        // The picture, number and title on the first row; what changed and
        // restore under it, across the card: in a narrow panel the title
        // and the summary each get the width
        return (
            <div
                className={cn(
                    "overflow-hidden rounded-xl border border-border bg-card",
                    className,
                )}
                data-testid="version-card"
                {...rest}
            >
                <div className="grid grid-cols-[auto_auto_minmax(0,1fr)_auto] items-center gap-x-2.5 gap-y-1 p-1.5 pr-2">
                    <button
                        type="button"
                        onClick={() => openCompare(version.id)}
                        className="sheet-light flex h-9 w-14 shrink-0 items-center justify-center overflow-hidden rounded-md border border-border bg-white hover:border-foreground/30"
                        aria-label={t.compare}
                        title={t.compare}
                    >
                        <VersionThumb
                            svg={version.svg}
                            className="max-h-8 max-w-[52px]"
                        />
                    </button>
                    {badge}
                    <div
                        className="col-span-2 truncate text-[13px] text-foreground"
                        title={title}
                    >
                        {title}
                    </div>
                    <div className="col-span-3 pl-1">{summaryLine}</div>
                    {restoreButton}
                </div>
                {children}
            </div>
        )
    }

    // Undo and redo belong to the newest change while it is (or was) on
    // the canvas; after an older version was restored, this one is
    // restored too
    const canUndo = source.canUndo || source.canRedo
    return (
        <div
            className={cn(
                "overflow-hidden rounded-xl border border-border bg-card",
                isOnCanvas && "border-foreground/15",
                className,
            )}
            data-testid="version-card"
            {...rest}
        >
            <button
                type="button"
                onClick={() => openCompare(version.id)}
                className="group/thumb sheet-light relative flex h-24 w-full items-center justify-center border-b border-border bg-white"
                aria-label={t.compare}
            >
                <VersionThumb
                    svg={version.svg}
                    dimmed={isUndone}
                    className="max-h-20 max-w-[88%]"
                />
                <span className="absolute right-2 bottom-2 rounded-md bg-black/60 px-1.5 py-0.5 text-[11px] text-white opacity-0 transition-opacity group-hover/thumb:opacity-100">
                    {t.compare}
                </span>
            </button>
            {/* Title row with the action; the summary runs under both */}
            <div className="grid grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-x-2.5 px-3 py-2.5">
                {badge}
                <div
                    className="truncate text-[13px] font-medium text-foreground"
                    title={title}
                >
                    {title}
                </div>
                {canUndo ? (
                    <button
                        type="button"
                        disabled={source.isBusy}
                        onClick={() =>
                            source.canRedo ? source.redo() : source.undo()
                        }
                        className={actionClass}
                        data-testid="version-undo"
                    >
                        {source.canRedo ? (
                            <Redo2 className="size-3.5" />
                        ) : (
                            <Undo2 className="size-3.5" />
                        )}
                        {source.canRedo ? t.redo : t.undo}
                    </button>
                ) : (
                    restoreButton
                )}
                <div className="col-span-2 col-start-2 mt-0.5">
                    {summaryLine}
                </div>
            </div>
            {children}
        </div>
    )
}
"use client"

import { type CSSProperties, type ElementType, memo, useMemo } from "react"
import { cn } from "@/lib/utils"

export type TextShimmerProps = {
    children: string
    as?: ElementType
    className?: string
    duration?: number
    spread?: number
}

const ShimmerComponent = ({
    children,
    as: Component = "p",
    className,
    duration = 2,
    spread = 2,
}: TextShimmerProps) => {
    const dynamicSpread = useMemo(
        () => (children?.length ?? 0) * spread,
        [children, spread],
    )

    return (
        <Component
            className={cn(
                "animate-shimmer relative inline-block bg-[length:250%_100%,auto] bg-clip-text text-transparent",
                "[--bg:linear-gradient(90deg,#0000_calc(50%-var(--spread)),var(--color-background),#0000_calc(50%+var(--spread)))] [background-repeat:no-repeat,padding-box]",
                className,
            )}
            style={
                {
                    "--spread": `${dynamicSpread}px`,
                    "--shimmer-duration": `${duration}s`,
                    backgroundImage:
                        "var(--bg), linear-gradient(var(--color-muted-foreground), var(--color-muted-foreground))",
                } as CSSProperties
            }
        >
            {children}
        </Component>
    )
}

export const Shimmer = memo(ShimmerComponent)
"use client"

import { createContext, useContext } from "react"
import type { ChangeSummary } from "@/lib/diagram-diff"

/** One saved state of the diagram, as the version card and the compare
 * dialog show it */
export interface VersionItem {
    id: string
    /** Shown as v{number} */
    number: number
    /** Full multi-page document */
    xml: string
    /** The page the change was made on; none: the first page */
    pageId?: string
    /** Document before the change, when it is known */
    beforeXml?: string
    /** SVG data URL thumbnail; undefined: still being made; "": none could
     * be made */
    svg?: string
    summary: ChangeSummary
    /** Drawn on an empty canvas (the card shows totals, not changes) */
    fromScratch?: boolean
    /** The cells the change added or changed, to outline them again */
    touchedIds?: string[]
}

/**
 * Where the versions come from and what can be done with them. The web app
 * fills it from the chat's version store; the MCP shell from the server's
 * history.
 */
export interface VersionsSource {
    versions: VersionItem[]
    /** The version the canvas shows now, or null (hand edits, undone) */
    onCanvasId: string | null
    /** The latest version, when its change was undone */
    undoneId: string | null
    /** The canvas was changed by hand since this version (no version is
     * on it now) */
    editedSinceId?: string | null
    /** Something is changing the canvas: version actions wait */
    isBusy: boolean
    /** The latest version's change can be undone */
    canUndo: boolean
    /** The latest version's change was undone and can be put back */
    canRedo: boolean
    restore: (id: string) => void
    undo: () => void
    redo: () => void
}

const VersionsContext = createContext<VersionsSource | null>(null)

export function VersionsProvider({
    value,
    children,
}: {
    value: VersionsSource
    children: React.ReactNode
}) {
    return (
        <VersionsContext.Provider value={value}>
            {children}
        </VersionsContext.Provider>
    )
}

export function useVersionsContext(): VersionsSource {
    const source = useContext(VersionsContext)
    if (!source) {
        throw new Error(
            "useVersionsContext must be used within a VersionsProvider",
        )
    }
    return source
}
import { create } from "zustand"

export type SettingsTab = "models" | "general" | "drawing" | "about"
/** The models tab: its provider list, the provider picker or a provider */
export type ModelsPage = "list" | "picker" | { providerId: string }
export type MobileView = "canvas" | "chat"

interface UiState {
    /** Desktop: the floating chat panel is open */
    panelOpen: boolean
    /** The start screen was put away (drawing by hand, an opened file) */
    heroDismissed: boolean
    /** Phones: which half of the app is visible */
    mobileView: MobileView
    settingsOpen: boolean
    settingsTab: SettingsTab
    modelsPage: ModelsPage
    /** Version shown in the compare dialog, or null when closed */
    compareVersionId: string | null
    saveDialogOpen: boolean
    /** Bumped to ask the composer to take focus */
    focusComposerToken: number
    setPanelOpen: (open: boolean) => void
    setHeroDismissed: (dismissed: boolean) => void
    togglePanel: () => void
    setMobileView: (view: MobileView) => void
    /** Opens on the given tab (else the last one); the models tab on its
     * list unless a page is given */
    openSettings: (tab?: SettingsTab, modelsPage?: ModelsPage) => void
    setSettingsOpen: (open: boolean) => void
    setSettingsTab: (tab: SettingsTab) => void
    setModelsPage: (page: ModelsPage) => void
    openCompare: (versionId: string) => void
    closeCompare: () => void
    setSaveDialogOpen: (open: boolean) => void
    focusComposer: () => void
}

export const useUiStore = create<UiState>((set) => ({
    panelOpen: true,
    heroDismissed: false,
    mobileView: "chat",
    settingsOpen: false,
    settingsTab: "models",
    modelsPage: "list",
    compareVersionId: null,
    saveDialogOpen: false,
    focusComposerToken: 0,
    setPanelOpen: (open) => set({ panelOpen: open }),
    setHeroDismissed: (dismissed) => set({ heroDismissed: dismissed }),
    togglePanel: () => set((state) => ({ panelOpen: !state.panelOpen })),
    setMobileView: (view) => set({ mobileView: view }),
    openSettings: (tab, modelsPage = "list") =>
        set((state) => ({
            settingsOpen: true,
            settingsTab: tab ?? state.settingsTab,
            modelsPage,
        })),
    setSettingsOpen: (open) => set({ settingsOpen: open }),
    setSettingsTab: (tab) => set({ settingsTab: tab }),
    setModelsPage: (page) => set({ modelsPage: page }),
    openCompare: (versionId) => set({ compareVersionId: versionId }),
    closeCompare: () => set({ compareVersionId: null }),
    setSaveDialogOpen: (open) => set({ saveDialogOpen: open }),
    focusComposer: () =>
        set((state) => ({
            panelOpen: true,
            mobileView: "chat",
            focusComposerToken: state.focusComposerToken + 1,
        })),
}))
import { Paintbrush, Sparkles } from "lucide-react"
import { ButtonTooltip } from "@/components/workspace/icon-button"
import { useDictionary } from "@/hooks/use-dictionary"
import { openFormatPanel } from "@/lib/drawio/editor-bridge"
import { isMac, modKey } from "@/lib/platform"
import { useCanvasStore } from "@/stores/canvas-store"
import { useUiStore } from "@/stores/ui-store"

const BUTTON_HEIGHT = 32
const BUTTON_WIDTH = 32
const GAP = 10

const iconButton =
    "flex h-full w-8 items-center justify-center rounded-xl transition-colors hover:bg-interactive-hover"

/**
 * Buttons next to the selected shapes. "Edit style" opens draw.io's format
 * panel, for changing colors by hand; it hides while the panel is open.
 * "Ask AI to change this" shows only while the chat panel is hidden (with
 * the panel open, the selection already shows as a chip in its input): it
 * opens the panel and moves focus to the input. Hidden while an answer is
 * changing the canvas.
 */
export function SelectionAsk({
    width,
    height,
}: {
    /** Size of the canvas area, for keeping the buttons inside it */
    width: number
    height: number
}) {
    const dict = useDictionary()
    const rect = useCanvasStore((s) => s.selectionRect)
    const selection = useCanvasStore((s) => s.selection)
    const isFreehand = useCanvasStore((s) => s.isFreehand)
    const isFormatOpen = useCanvasStore((s) => s.isFormatOpen)
    const popupOpen = useCanvasStore((s) => s.isDrawioPopupOpen)
    const isBusy = useCanvasStore((s) => s.isBusy)
    const focusComposer = useUiStore((s) => s.focusComposer)
    const panelOpen = useUiStore((s) => s.panelOpen)

    const showAsk = !panelOpen
    const showStyle = !isFormatOpen
    if (isBusy || popupOpen || !rect || selection.length === 0 || isFreehand) {
        return null
    }
    if (!showAsk && !showStyle) return null
    // Selection scrolled out of view
    if (
        rect.x + rect.width < 0 ||
        rect.y + rect.height < 0 ||
        rect.x > width ||
        rect.y > height
    ) {
        return null
    }

    // Above the selection, starting past its right edge (connectors from
    // above end at the middle of its top), kept inside the canvas
    const barWidth = (showAsk && showStyle ? 2 : 1) * BUTTON_WIDTH + 4
    const left = Math.min(
        Math.max(8, rect.x + rect.width + GAP),
        width - barWidth - 8,
    )
    const above = rect.y - BUTTON_HEIGHT - GAP
    const top =
        above > 64
            ? above
            : Math.min(rect.y + rect.height + GAP, height - BUTTON_HEIGHT - 72)

    return (
        <div
            className="pointer-events-auto absolute z-10 flex h-8 items-center rounded-xl bg-card text-foreground shadow-pop animate-fade-in"
            style={{ left, top }}
        >
            {showAsk && (
                <ButtonTooltip
                    label={dict.workspace.askAi}
                    shortcut={`${modKey}/`}
                    side="top"
                >
                    <button
                        type="button"
                        onClick={focusComposer}
                        className={iconButton}
                        aria-label={dict.workspace.askAi}
                        data-testid="selection-ask"
                    >
                        <Sparkles className="size-4 text-marker-ink" />
