export interface DrawioExportEvent {
    event: "export"
    format: string
    data: string
    xml: string
    message: { message?: string; [key: string]: unknown }
}

export interface DrawioFrameHandle {
    load: (data: { xml: string }) => void
    exportDiagram: (data: {
        format: string
        message?: string
        [key: string]: unknown
    }) => void
