                    <DialogTitle className="sr-only">
                        {dict.modelConfig.selectModel}
                    </DialogTitle>
                    <Command className="**:data-[slot=command-input-wrapper]:h-auto">
                        <CommandInput
                            className="h-auto py-3.5"
                            placeholder={dict.modelConfig.searchModels}
                        />
                        <div className="flex flex-1 flex-col min-h-0 overflow-hidden">
                            <div className="flex-1 min-h-0 overflow-hidden">
                                <ModelList
                                    className="overflow-y-auto scrollbar-thin"
                                    label={dict.modelConfig.models}
                                >
                                    <CommandEmpty>
                                        {dict.modelConfig.noModelsFound}
                                    </CommandEmpty>

                                    {/* Server Default Option - only show when no server models are configured */}
                                    {serverModels.length === 0 && (
                                        <CommandGroup
                                            heading={dict.modelConfig.default}
                                        >
                                            <CommandItem
                                                value="__server_default__"
                                                onSelect={handleSelect}
                                                className={cn(
                                                    "cursor-pointer",
                                                    !selectedModelId &&
                                                        "bg-accent",
                                                )}
                                            >
                                                <Check
                                                    className={cn(
                                                        "mr-2 h-4 w-4",
                                                        !selectedModelId
                                                            ? "opacity-100"
                                                            : "opacity-0",
                                                    )}
                                                />
                                                <Server className="mr-2 h-4 w-4 text-muted-foreground" />
                                                <span className="flex-1 truncate text-left">
                                                    {
                                                        dict.modelConfig
                                                            .serverDefault
                                                    }
                                                </span>
                                            </CommandItem>
                                        </CommandGroup>
                                    )}

                                    {/* Server Models Section */}
                                    {serverModels.length > 0 && (
                                        <>
                                            <SectionHeader
                                                icon={<Monitor />}
                                                label={
                                                    dict.modelConfig
                                                        .serverModels
                                                }
                                            />
                                            {demoServer && (
                                                <p className="mx-1 px-2 pt-1.5 text-xs text-muted-foreground">
                                                    {
                                                        dict.modelConfig
                                                            .demoModelNote
                                                    }
                                                </p>
                                            )}
                                            {renderGroups(
                                                groupedServerModels,
                                                "server",
                                                (model) =>
                                                    model.isDefault && (
                                                        <span
                                                            title={
                                                                dict.modelConfig
                                                                    .serverDefaultModel
                                                            }
                                                            className="ml-auto text-xs text-muted-foreground"
                                                        >
                                                            {
                                                                dict.modelConfig
                                                                    .default
                                                            }
                                                        </span>
                                                    ),
                                            )}
                                        </>
                                    )}

                                    {/* User Models Section */}
                                    {userModels.length > 0 && (
                                        <>
                                            {serverModels.length > 0 && (
                                                <CommandSeparator />
