                                <div
                                    className="relative z-10 shrink-0 space-y-0.5 border-t bg-background px-3 py-2"
                                    // The search's Enter would pick the highlighted
                                    // model instead of pressing the button
                                    onKeyDown={(e) => e.stopPropagation()}
