                                            className={footerButton}
                                        >
                                            <Plus className="h-4 w-4 shrink-0 text-muted-foreground" />
                                            <span className="truncate">
                                                {
                                                    dict.modelConfig
                                                        .addProviderEntry
                                                }
                                            </span>
                                        </button>
