                                        >
                                            <Settings2 className="h-4 w-4 shrink-0 text-muted-foreground" />
                                            <span className="truncate">
                                                {
                                                    dict.modelConfig
                                                        .configureModels
                                                }
                                            </span>
                                        </button>
