                                                return
                                            }
                                            if (e.key === "Enter") {
                                                addCustomModel()
                                            }
                                        }}
                                        className={cn(
                                            "h-8 rounded-lg font-mono text-xs",
                                            duplicateError &&
                                                "border-destructive focus-visible:ring-destructive",
                                        )}
                                    />
                                    {duplicateError && (
                                        <p className="mt-1 text-[11px] text-destructive">
                                            {duplicateError}
                                        </p>
                                    )}
                                </div>
                                <Button
                                    variant="outline"
                                    size="sm"
                                    className="h-8 rounded-lg"
                                    onClick={addCustomModel}
                                    disabled={!customModelInput.trim()}
                                >
                                    {t.add}
                                </Button>
                                {/* Nothing to browse for a provider without
                                    suggested models, until its list is fetched.
                                    modal: the dialog blocks the wheel outside
                                    itself, and the list is rendered outside it */}
                                {suggestedModels.length > 0 && (
                                    <Popover
                                        modal
                                        open={modelPickerOpen}
                                        onOpenChange={setModelPickerOpen}
                                    >
                                        <PopoverTrigger asChild>
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                className="h-8 rounded-lg text-xs"
                                                disabled={
                                                    availableSuggestions.length ===
                                                    0
                                                }
                                            >
                                                {availableSuggestions.length ===
                                                0
                                                    ? t.allAdded
                                                    : t.browseModels}
                                            </Button>
                                        </PopoverTrigger>
                                        <PopoverContent
                                            className="w-80 p-0"
                                            align="end"
                                        >
                                            <Command>
                                                <CommandInput
                                                    placeholder={t.searchModels}
                                                />
                                                {fromCatalog && (
                                                    <p className="border-b px-3 py-2 text-xs text-muted-foreground">
                                                        {formatMessage(
                                                            t.catalogModelsNote,
                                                            {
                                                                name: providerName(
                                                                    provider,
                                                                ),
                                                            },
                                                        )}
                                                    </p>
                                                )}
                                                <CommandList
                                                    className="max-h-72"
                                                    label={t.models}
                                                >
                                                    <CommandEmpty>
                                                        {t.noModelsFound}
                                                    </CommandEmpty>
                                                    {availableSuggestions.map(
                                                        (model) => (
                                                            <CommandItem
                                                                key={model.id}
                                                                value={model.id}
                                                                onSelect={() => {
                                                                    handleAddModel(
                                                                        model.id,
                                                                    )
                                                                    setModelPickerOpen(
                                                                        false,
                                                                    )
                                                                }}
                                                                className="font-mono text-xs"
                                                            >
                                                                <span className="truncate">
                                                                    {model.id}
                                                                </span>
                                                                {supportsTools(
                                                                    model,
                                                                ) === false ? (
                                                                    <span className="ml-auto shrink-0 font-sans text-[10px] text-amber-600 dark:text-amber-400">
                                                                        {
                                                                            t.noTools
                                                                        }
                                                                    </span>
                                                                ) : (
                                                                    readsImages(
                                                                        model.id,
                                                                    ) ===
                                                                        false && (
                                                                        <span className="ml-auto shrink-0 font-sans text-[10px] text-muted-foreground">
                                                                            {
                                                                                t.noImages
                                                                            }
                                                                        </span>
                                                                    )
                                                                )}
                                                            </CommandItem>
                                                        ),
                                                    )}
                                                </CommandList>
                                            </Command>
                                        </PopoverContent>
                                    </Popover>
                                )}
                            </div>
                        </Step>

                        {/* 3: test */}
                        <Step n={3} done={allWork} title={t.stepTest}>
                            {/* Always on the page, so a screen reader reads
                                out the result when it arrives */}
                            <p
                                id={resultId}
                                role="status"
                                className="sr-only"
                                data-testid="test-result"
                            >
                                {testPassed
                                    ? passedText
                                    : testFailed
                                      ? validationError
                                      : ""}
                            </p>
                            {testPassed ? (
                                <div className="space-y-3 rounded-xl border border-success/20 bg-success-muted/70 px-4 py-3.5">
                                    <p className="flex items-start gap-2 text-[13px] font-medium text-success">
                                        <CheckCircle2 className="mt-0.5 size-4 shrink-0" />
                                        {/* A long model id wraps */}
                                        <span className="min-w-0 [overflow-wrap:anywhere]">
                                            {passedText}
                                            {lastSeconds && (
                                                <span className="ml-2 text-xs font-normal opacity-80">
                                                    {formatMessage(
                                                        t.answeredIn,
                                                        {
                                                            seconds:
                                                                lastSeconds,
                                                        },
                                                    )}
                                                </span>
                                            )}
                                        </span>
                                    </p>
                                    <div className="flex flex-wrap gap-2">
                                        {firstWorking && (
                                            <Button
                                                ref={useButtonRef}
                                                className="h-9 max-w-full rounded-lg px-4"
                                                disabled={chatLocked}
                                                aria-describedby={resultId}
                                                title={formatMessage(
                                                    t.useInChat,
                                                    {
                                                        model: firstWorking.modelId,
                                                    },
                                                )}
                                                onClick={() => {
                                                    modelConfig.setSelectedModelId(
                                                        firstWorking.id,
                                                    )
                                                    useUiStore
                                                        .getState()
                                                        .setSettingsOpen(false)
                                                }}
                                            >
                                                <span className="truncate">
                                                    {formatMessage(
                                                        t.useInChat,
                                                        {
                                                            model: firstWorking.modelId,
                                                        },
                                                    )}
                                                </span>
                                            </Button>
                                        )}
                                        <Button
                                            ref={backButtonRef}
                                            variant="outline"
                                            className="h-9 rounded-lg bg-background px-4"
                                            aria-describedby={resultId}
                                            onClick={() =>
                                                setModelsPage("list")
                                            }
                                        >
                                            {t.backToProviders}
                                        </Button>
                                    </div>
                                </div>
                            ) : (
                                <>
                                    <p className="text-xs text-muted-foreground">
                                        {t.testHint}
                                    </p>
                                    <div className="flex flex-wrap items-center gap-3">
                                        <Button
                                            // Not disabled while it runs: the
                                            // focus would leave it
                                            onClick={() => {
                                                if (!testing) handleValidate()
                                            }}
                                            disabled={!canTest}
                                            aria-disabled={testing || undefined}
                                            className="h-9 max-w-full rounded-lg px-4"
                                            title={testLabel}
                                            data-testid="test-models"
                                        >
                                            {validationStatus ===
                                                "validating" && (
                                                <Loader2 className="size-4 animate-spin" />
                                            )}
                                            <span className="truncate">
                                                {testLabel}
                                            </span>
                                        </Button>
                                        {testFailed && (
                                            <p className="flex items-center gap-1 text-xs text-destructive">
                                                <X className="size-3" />
                                                {validationError}
                                            </p>
                                        )}
                                    </div>
                                    {testBlocker && (
                                        <p className="text-xs text-muted-foreground">
                                            {testBlocker}
                                        </p>
                                    )}
                                </>
                            )}
                        </Step>

                        <button
                            type="button"
                            onClick={() => setDeleteConfirmOpen(true)}
                            className="flex items-center gap-1.5 text-xs text-destructive hover:underline"
                        >
                            <Trash2 className="size-3.5" />
                            {formatMessage(
                                models.length === 0
                                    ? t.deleteProviderOnly
                                    : models.length === 1
                                      ? t.deleteProviderNamedOne
                                      : t.deleteProviderNamedOther,
                                {
                                    name: providerName(provider),
                                    count: models.length,
                                },
                            )}
                        </button>
                    </div>
                </ScrollArea>
            </div>
        )
    }

    return (
        <>
            <div ref={pageRef} className="flex min-h-0 flex-1 flex-col">
                {selectedProvider ? (
                    renderProviderPage(selectedProvider)
                ) : page === "picker" ? (
                    <ProviderPicker
                        added={config.providers.map((p) => p.provider)}
                        onPick={handleAddProvider}
                        onBack={() => setModelsPage("list")}
                    />
                ) : (
                    <ProvidersList
                        providers={config.providers}
                        serverModels={modelConfig.models.filter(
                            (m) => m.source === "server",
                        )}
                        selectedModelId={modelConfig.selectedModelId}
                        onOpen={openProvider}
                        onAdd={handleAddProvider}
                        onBrowse={() => setModelsPage("picker")}
                    />
                )}
            </div>

            {/* Delete Confirmation Dialog */}
            <AlertDialog
                open={deleteConfirmOpen}
                onOpenChange={setDeleteConfirmOpen}
            >
                <AlertDialogContent className="border-destructive/30">
                    <AlertDialogHeader>
                        <div className="mx-auto mb-3 p-3 rounded-full bg-destructive/10">
                            <AlertCircle className="h-6 w-6 text-destructive" />
                        </div>
                        <AlertDialogTitle className="text-center">
                            {t.deleteProvider}
                        </AlertDialogTitle>
                        <AlertDialogDescription className="text-center">
                            {formatMessage(t.deleteConfirmDesc, {
                                name: selectedProvider
                                    ? providerName(selectedProvider)
                                    : "this provider",
                            })}
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>{t.cancel}</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDeleteProvider}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                            {t.delete}
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </>
    )
}
