// The chat panel answers a built-in example from here, without a request.
// Examples that come with a file only match when that exact example file is
// attached, so a user's own file with the same prompt still goes to the model.
export function findCachedResponse(
    promptText: string,
    hasImage: boolean,
    fileName?: string,
): CachedResponse | undefined {
    return CACHED_EXAMPLE_RESPONSES.find(
        (c) =>
            c.promptText === promptText &&
            c.hasImage === hasImage &&
            (!c.fileName || c.fileName === fileName),
    )
}
import type { getSelectedAIConfig } from "@/hooks/use-model-config"

type AIConfig = ReturnType<typeof getSelectedAIConfig>

/**
 * Request headers for /api/chat: the access code, the user's own provider
 * credentials (when a client-side model is selected) and per-request options.
 */
export function buildChatHeaders(
    config: AIConfig,
    options: { minimalStyle: boolean; maxOutputTokens: string },
): Record<string, string> {
    const headers: Record<string, string> = {
        "x-access-code": config.accessCode,
    }
    const set = (name: string, value: string | undefined) => {
        if (value) headers[name] = value
    }
    if (config.aiProvider) {
        set("x-ai-provider", config.aiProvider)
        set("x-ai-base-url", config.aiBaseUrl)
        set("x-ai-api-key", config.aiApiKey)
        set("x-ai-model", config.aiModel)
        // AWS Bedrock credentials
        set("x-aws-access-key-id", config.awsAccessKeyId)
        set("x-aws-secret-access-key", config.awsSecretAccessKey)
        set("x-aws-region", config.awsRegion)
        set("x-aws-session-token", config.awsSessionToken)
        // Vertex AI credentials (Express Mode)
        set("x-vertex-api-key", config.vertexApiKey)
        set("x-ai-thinking-enabled", config.thinkingEnabled)
    }
    // Selected model ID for server model lookup (apiKeyEnv/baseUrlEnv)
    set("x-selected-model-id", config.selectedModelId)
    if (options.minimalStyle) headers["x-minimal-style"] = "true"
    set("x-max-output-tokens", options.maxOutputTokens)
    return headers
}
/**
 * Logger for MCP server
 *
 * CRITICAL: MCP servers communicate via STDIO (stdin/stdout).
 * Using console.log() will corrupt the JSON-RPC protocol messages.
 * ALL logging MUST use console.error() which writes to stderr.
 */

export const log = {
    info: (msg: string, ...args: unknown[]) => {
        console.error(`[MCP-DrawIO] [INFO] ${msg}`, ...args)
    },
    error: (msg: string, ...args: unknown[]) => {
        console.error(`[MCP-DrawIO] [ERROR] ${msg}`, ...args)
    },
    debug: (msg: string, ...args: unknown[]) => {
        // process is missing when the web app runs this code in the browser
        if (typeof process !== "undefined" && process.env.DEBUG === "true") {
            console.error(`[MCP-DrawIO] [DEBUG] ${msg}`, ...args)
        }
    },
    warn: (msg: string, ...args: unknown[]) => {
        console.error(`[MCP-DrawIO] [WARN] ${msg}`, ...args)
    },
}
/**
 * Parse space-separated tokens to an array of strings.
 *
 * @param {string} value
 *   Space-separated tokens.
 * @returns {Array<string>}
 *   List of tokens.
 */
export function parse(value) {
  const input = String(value || '').trim()
  return input ? input.split(/[ \t\n\r\f]+/g) : []
}

/**
 * Serialize an array of strings as space separated-tokens.
 *
 * @param {Array<string|number>} values
 *   List of tokens.
 * @returns {string}
 *   Space-separated tokens.
 */
export function stringify(values) {
  return values.join(' ').trim()
}
